import { Logout } from '@mesx/common-ui-lib';
import type { Component } from 'vue';
import { createRouter, createWebHistory } from 'vue-router';
import { useProfileStore } from '../Auth/store/user-auth-store';
import loadingComponentRaw from '../global-components/reusable/loading-component.vue';
import unauthorizedRaw from '../global-components/reusable/unauthorized-component.vue';
import { useBomProfileStore } from '../modules/bom/store/bom-auth-store.ts';
import { useOperationProfileStore } from '../modules/operation/store/operation-auth-store.ts';
import { appLogger } from '../utils/logger/app-logger.ts';
import bomVisualizationViewRaw from '@/modules/bom/views/bom-visualization-view.vue';
import materialConfigViewRaw from '@/modules/material/views/material-config-view.vue';
import operationConfigViewRaw from '@/modules/operation/views/operation-config-view.vue';

const loadingComponent = loadingComponentRaw as Component;
const unauthorized = unauthorizedRaw as Component;
const bomVisualizationView = bomVisualizationViewRaw as unknown as Component;
const materialConfigView = materialConfigViewRaw as unknown as Component;
const operationConfigView = operationConfigViewRaw as unknown as Component;
const logoutComponent = Logout as unknown as Component;

/**
 *
 */
async function handleLoginAgain(): Promise<void> {
  const profileStore = useProfileStore();
  await profileStore.initializeAuthentication();
}

const routes = [
  {
    component: logoutComponent,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: handleLoginAgain,
    },
  },
  {
    component: unauthorized,
    name: 'Unauthorized',
    path: '/unauthorized',
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
  {
    component: materialConfigView,
    meta: { requiresAuth: true, title: 'Material model configuration' },
    name: 'materials-filtered',
    path: '/mstr-set-ui/material-ui',

  },
  {
    component: operationConfigView,
    meta: { requiresAuth: true, title: 'Operation Model', useOperationAuth: true },
    name: 'operation-config',
    path: '/mstr-set-ui/operation-ui',
  },
  {
    component: bomVisualizationView,
    meta: { requiresAuth: true, title: 'BOM Visualization', useBomAuth: true },
    name: 'bom-visualization',
    path: '/mstr-set-ui/bom-visualization',
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (typeof to.meta.title === 'string' && to.meta.title !== '') {
    document.title = `MESX.0 - ${to.meta.title}`;
  }

  if (to.meta.requiresAuth !== true) {
    return next();
  }

  let authStore;
  if (to.meta.useOperationAuth === true) {
    authStore = useOperationProfileStore();
  }
  else if (to.meta.useBomAuth === true) {
    authStore = useBomProfileStore();
  }
  else {
    authStore = useProfileStore();
  }

  try {
    await authStore.authenticateUser();
    const user = await authStore.getUser();
    if (user !== undefined && user !== null) {
      await authStore.fetchUserAttributes();
      await authStore.authorizeUser();
    }
    else {
      console.error('User not found');
      return next('/unauthorized');
    }
    return next();
  }
  catch (error) {
    appLogger.error(
      `Error during authentication or authorization: ${String(error)}`,
    );
    return next('/unauthorized');
  }
});

export { router };

