const baseUrl = import.meta.env.MASTER_BE_URL as string;
const token = import.meta.env.TOKEN as string;
const BOM_DEFINITION_PATH = '/isa95-bom-operations-model/bom-definitions';

export type BomStatus = 'Active' | 'Inactive';

