interface ApiClient {
  get<T>(url: string, config?: unknown): Promise<AxiosResponse<T>>
}

interface WrappedApiResponse<T> {
  success: boolean
  statusCode: number
  messages?: Array<string>
  data?: T | null
}

interface BomVisualizationOptions {
  materialCode: string
  materialDescription?: string
}

const axios: ApiClient = {
  get: async (url: string, config?: unknown) =>
    axiosLib.get(url, config as Record<string, unknown>),
};

/**
 * Build authorization headers when token is available.
 * @returns Headers object with bearer token, or empty object.
 */
function authHeaders(): Record<string, string> {
  if (typeof token === 'string' && token.length > 0) {
    return { authorization: `Bearer ${token}` };
  }

  return {};
}

/**
 * @param payload payload to check
 * @returns true if payload is a wrapped API response, false otherwise
 */
function isWrappedApiResponse<T>(
  payload: WrappedApiResponse<T> | T | undefined,
): payload is WrappedApiResponse<T> {
  return (
    typeof payload === 'object'
    && payload !== null
    && 'success' in payload
    && typeof (payload as { success?: unknown }).success === 'boolean'
    && 'statusCode' in payload
  );
}

/**
 * Resolve a user-friendly message from a wrapped API response, with fallback.
 * @param payload API response payload to extract message from
 * @param fallbackMessage Fallback message to use if no messages are found.
 * @returns Resolved message string from the payload or the fallback when necessary.
 */
function resolveWrappedMessage<T>(
  payload: WrappedApiResponse<T>,
  fallbackMessage: string,
): string {
  return payload.messages?.find(message => message.trim() !== '') ?? fallbackMessage;
}

/**
 *  Unwrap API response payloads, handling both wrapped and unwrapped formats.
 * @param payload   API response payload that may be wrapped or unwrapped.
 * @param fallbackMessage   Fallback message to use if the payload indicates an error without messages.
 * @returns The unwrapped data when successful, or undefined when no data is present.
 */
function unwrapApiPayload<T>(
  payload: WrappedApiResponse<T> | T | undefined,
  fallbackMessage: string,
): T | undefined {
  if (!isWrappedApiResponse(payload)) {
    return payload;
  }

  if (!payload.success && payload.statusCode === 400) {
    throw new Error(resolveWrappedMessage(payload, fallbackMessage));
  }

  return payload.data ?? undefined;
}

/**
 * Convert nullable API strings into a stable display placeholder.
 * @param value Raw nullable text.
 * @returns Original text or a dash placeholder.
 */
function formatEmpty(value: string | null | undefined): string {
  return value === null || value === undefined || value.trim() === '' ? '-' : value;
}

/**
 * Convert backend use-type codes into readable labels.
 * @param value Raw use-type value from the BOM API.
 * @returns Display-ready use-type string.
 */
function formatUseType(value: string | null | undefined): string {
  if (value === '1') {
    return 'Consumed';
  }

  if (value === '3') {
    return 'Produced';
  }

  return formatEmpty(value);
}

/**
 * Format numeric quantities without noisy trailing decimals.
 * @param value Raw numeric quantity.
 * @returns Display-ready quantity.
 */
function formatQuantity(value: number): string {
  return Number.isInteger(value)
    ? String(value)
    : String(Number.parseFloat(value.toFixed(3)));
}

/**
 * Convert nested BOM API items into recursive component rows for the UI.
 * @param component Raw BOM item from the API.
 * @returns Recursive component row DTO.
 */
function mapBomItemToComponent(component: BomItemApi): BomComponentRowDto {
  const children = component.bomItems?.map(child => mapBomItemToComponent(child)) ?? [];

  return {
    children,
    hasChildren: component.hasChildren === true || children.length > 0,
    isPhantom: component.isPhantom === true,
    relationship: component.isPhantom === true ? 'Phantom' : 'Component',
    itemNumber: String(component.id),
    materialCode: component.materialDefinitionCode ?? String(component.materialDefinitionId),
    materialDefinitionId: component.materialDefinitionId,
    quantity: formatQuantity(component.quantity),
    uom: component.quantityUOM,
    useType: formatUseType(component.useType),
  };
}

/**
 * Count all nested BOM items recursively.
 * @param components Recursive component rows.
 * @returns Total count including descendants.
 */
function countBomComponents(components: Array<BomComponentRowDto>): number {
  return components.reduce(
    (total, component) => total + 1 + countBomComponents(component.children ?? []),
    0,
  );
}

/**
 * Fetch a BOM definition by material definition ID and plant.
 * @param materialDefinitionId Material definition ID selected in the BOM view.
 * @param plant Plant identifier.
 * @returns BOM API payload or null when no BOM exists.
 */
async function fetchBomDefinition(
  materialDefinitionId: number,
  plant: number,
): Promise<BomApi | null> {
  try {
    const response: AxiosResponse<
      BomApi
      | WrappedApiResponse<BomApi>
      | undefined
    > = await axios.get(
      `${baseUrl}${BOM_DEFINITION_PATH}`,
      {
        headers: {
          ...authHeaders(),
          accept: '*/*',
        },
        params: {
          materialDefinitionId,
          plant,
        },
      },
    );

    const payload = unwrapApiPayload(
      response.data,
      `Failed to retrieve BOM for material ${materialDefinitionId} and plant ${plant}`,
    );

    return payload ?? null;
  }
  catch (error) {
    if (isAxiosError(error) && error.response?.status === 404) {
      return null;
    }

    throw error;
  }
}

/**
 * Map the BOM API payload to the visualization DTO used by the view.
 * @param item Raw BOM API record.
 * @param options Selected material metadata for the header.
 * @returns Normalized BOM visualization DTO.
 */
function mapBomApiToVisualization(
  item: BomApi,
  options: BomVisualizationOptions,
): BomVisualizationDto {
  const components = item.bomItems.map(component => mapBomItemToComponent(component));

  return {
    components,
    header: {
      alternativeBom: item.alternativeBom,
      bomId: String(item.id),
      description: formatEmpty(item.description),
      effectiveEndDate: formatEmpty(item.effectiveEndDate),
      effectiveStartDate: item.effectiveStartDate,
      erpIdentifier: item.erpIdentifier,
      erpSource: item.erpSource,
      materialCode: options.materialCode,
      materialDefinitionId: item.materialDefinitionId,
      materialDescription: options.materialDescription ?? options.materialCode,
      operationDefinition: formatEmpty(item.operationDescription),
      plant: item.plant,
      status: item.status,
      useType: formatUseType(item.useType),
    },
    note: `${countBomComponents(components)} components loaded from the BOM API.`,
  };
}

/**
 * Load BOM visualization data for the selected material definition.
 * @param materialDefinitionId Material definition ID selected in the search.
 * @param plant Plant context from the user profile.
 * @param options Selected material metadata for the header.
 * @returns Normalized BOM visualization data when found.
 */
export async function getBomVisualization(
  materialDefinitionId: number,
  plant: number,
  options: BomVisualizationOptions,
): Promise<BomVisualizationDto | null> {
  const record = await fetchBomDefinition(materialDefinitionId, plant);
  return record === null ? null : mapBomApiToVisualization(record, options);
}

/**
 * Load child BOM items for a row whose material has children.
 * @param materialDefinitionId Material definition ID from the row to expand.
 * @param plant Plant context from the user profile.
 * @returns Recursive child component rows.
 */
export async function getBomChildren(
  materialDefinitionId: number,
  plant: number,
): Promise<Array<BomComponentRowDto>> {
  const record = await fetchBomDefinition(materialDefinitionId, plant);

  if (record === null) {
    return [];
  }

  return record.bomItems.map(component => mapBomItemToComponent(component));
}

