const redirectUri: string
  = (import.meta.env.APP_REDIRECT_URI as string | undefined) ?? '';
let appBasePath: string;
if (redirectUri !== '') {
  const parts: Array<string> = redirectUri.split('/');
  appBasePath = parts.pop() ?? '';
}

const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, token, BOM_APP_NAME);
const userAttributesManager = new UserAttributesManager(apiService);

export const useBomProfileStore = defineStore('bom-user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      const { profile } = user;
      const fetchedUser = await apiService.getUserByEmail(profile.email);
      if (fetchedUser !== null && fetchedUser !== undefined) {
        localStorage.setItem('userId', fetchedUser.userId);
        await apiService.updateUserLastLoginByEmail(
          fetchedUser.email,
          new Date(),
        );
      }
      else {
        const userDetails = {
          firstName: profile.given_name,
          lastName: profile.family_name,
          email: profile.email,
          lastLogin: new Date(),
        };
        await apiService.saveUser(userDetails);
      }
      useUser.setProfile(`${profile.given_name} ${profile.family_name}`);
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes
          = userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes !== null && userAttributes !== undefined) {
          this.userAttributes = { ...userAttributes };
        }
        else {
          appLogger.warn('No user attributes found.');
        }
      }
      catch (error: unknown) {
        appLogger.error(
          `Error fetching user attributes: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    },
    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        await authService.logout();
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
      }
      catch {
        appLogger.error('Log out failed');
      }
    },
  },
  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    managedBy: '',
    profile: '',
    userAttributes: {} as Record<string, string>,
    user: undefined as User | undefined,
  }),
});

import { defineStore } from 'pinia';
import type { QTableColumn } from 'quasar';
import { computed, ref } from 'vue';
import {
  getMaterialSuggestions,
} from '../../material/service/api.ts';
import type { MaterialSuggestionDto } from '../../material/service/interfaces/api.interface.ts';
import {
  getBomChildren,
  getBomVisualization,
  type BomComponentRowDto,
  type BomMaterialSuggestionDto,
  type BomVisualizationDto,
} from '../service/api.ts';

export type BomTableRow = BomComponentRowDto & {
  children: Array<BomTableRow>
  isChildrenLoaded: boolean
  level: number
  parentRowId?: string
  rowId: string
};

const ROWS_PER_PAGE = 5;

const bomColumns: Array<QTableColumn<BomTableRow>> = [
  { align: 'left', field: 'materialCode', label: 'Material', name: 'materialCode' },
  { align: 'left', field: 'useType', label: 'Use Type', name: 'useType' },
  { align: 'left', field: 'quantity', label: 'Quantity', name: 'quantity' },
  { align: 'right', field: 'materialCode', label: '', name: 'actions' },
];

/**
 * Convert a BOM component DTO into a table row with tree metadata.
 * @param component Component row received from the BOM API mapper.
 * @param parentRowId Optional parent row ID for nested children.
 * @param level Visible nesting level for indentation.
 * @returns BOM table row with stable row identifiers.
 */
function mapBomRow(
  component: BomComponentRowDto,
  parentRowId?: string,
  level = 0,
): BomTableRow {
  const rowId = parentRowId === undefined
    ? `${component.materialDefinitionId}-${component.itemNumber}`
    : `${parentRowId}-${component.materialDefinitionId}-${component.itemNumber}`;
  const children = component.children?.map(child => mapBomRow(child, rowId, level + 1)) ?? [];

  return {
    ...component,
    children,
    isChildrenLoaded: !component.hasChildren || children.length > 0,
    level,
    parentRowId,
    rowId,
  };
}

/**
 * Count all currently loaded rows, including nested descendants.
 * @param rows BOM rows to count.
 * @returns Total row count.
 */
function countBomRows(rows: Array<BomTableRow>): number {
  return rows.reduce(
    (total, row) => total + 1 + countBomRows(row.children),
    0,
  );
}

/**
 * Flatten a tree of rows to the currently visible rows based on expansion state.
 * @param rows Root BOM rows.
 * @param expandedRowIds Row IDs that are currently expanded.
 * @returns Flat list of rows in display order.
 */
function flattenExpandedRows(
  rows: Array<BomTableRow>,
  expandedRowIds: Set<string>,
): Array<BomTableRow> {
  return rows.flatMap((row) => {
    if (!expandedRowIds.has(row.rowId) || row.children.length === 0) {
      return [row];
    }

    return [row, ...flattenExpandedRows(row.children, expandedRowIds)];
  });
}

/**
 * Find a row anywhere in the BOM tree.
 * @param rows BOM row tree.
 * @param rowId Row identifier to find.
 * @returns Matching row when found.
 */
function findBomRow(rows: Array<BomTableRow>, rowId: string): BomTableRow | undefined {
  for (const row of rows) {
    if (row.rowId === rowId) {
      return row;
    }

    const nestedMatch = findBomRow(row.children, rowId);
    if (nestedMatch !== undefined) {
      return nestedMatch;
    }
  }

  return undefined;
}

/**
 * Replace a single row in the BOM tree without mutating the existing structure.
 * @param rows BOM row tree.
 * @param rowId Target row identifier.
 * @param updater Row update function.
 * @returns Updated BOM row tree.
 */
function replaceBomRow(
  rows: Array<BomTableRow>,
  rowId: string,
  updater: (row: BomTableRow) => BomTableRow,
): Array<BomTableRow> {
  return rows.map((row) => {
    if (row.rowId === rowId) {
      return updater(row);
    }

    if (row.children.length === 0) {
      return row;
    }

    return {
      ...row,
      children: replaceBomRow(row.children, rowId, updater),
    };
  });
}

export const useBomStore = defineStore('bom', () => {
  const plant = ref(1146);
  const selectedMaterialCode = ref<string | undefined>(undefined);
  const selectedMaterialDescription = ref<string | undefined>(undefined);
  const selectedMaterialDefinitionId = ref<number | undefined>(undefined);
  const selectedBom = ref<BomVisualizationDto | null>(null);
  const suggestions = ref<Array<BomMaterialSuggestionDto>>([]);
  const componentTree = ref<Array<BomTableRow>>([]);
  const expandedRowIds = ref<Array<string>>([]);
  const isLoadingBom = ref(false);
  const isLoadingSuggestions = ref(false);
  const loadingRowIds = ref<Array<string>>([]);
  const bomTablePagination = ref({
    page: 1,
    rowsPerPage: ROWS_PER_PAGE,
    sortBy: '',
    descending: false,
  });

  const selectedMaterialLabel = computed(() => {
    if (selectedMaterialCode.value === undefined) {
      return '';
    }

    if (
      selectedMaterialDescription.value === undefined
      || selectedMaterialDescription.value === ''
    ) {
      return selectedMaterialCode.value;
    }

    return `${selectedMaterialCode.value} - ${selectedMaterialDescription.value}`;
  });

  const componentRows = computed<Array<BomTableRow>>(() => componentTree.value);
  const expandedRows = computed<Array<BomTableRow>>(() =>
    flattenExpandedRows(componentTree.value, new Set(expandedRowIds.value)),
  );
  const parentComponentRows = computed<Array<BomTableRow>>(() => expandedRows.value);
  const parentComponentCount = computed(() => countBomRows(componentTree.value));

  /**
   * Store the current plant context for BOM calls.
   * @param newPlant Plant identifier from the user profile.
   */
  function setPlant(newPlant: number): void {
    if (Number.isFinite(newPlant) && newPlant > 0) {
      plant.value = newPlant;
    }
  }

  /**
   * Reset BOM table pagination to the first page.
   */
  function resetTablePage(): void {
    bomTablePagination.value.page = 1;
  }

  /**
   * Load search suggestions from the material service.
   * @param search Search term from the BOM material input.
   */
  async function loadSuggestions(search?: string): Promise<void> {
    let apiSuggestions: Array<MaterialSuggestionDto> = [];

    isLoadingSuggestions.value = true;
    try {
      apiSuggestions = await getMaterialSuggestions(plant.value, search);
    }
    catch (error) {
      console.warn('Unable to load material suggestions for BOM visualization.', error);
    }
    finally {
      isLoadingSuggestions.value = false;
    }

    suggestions.value = apiSuggestions.map(suggestion => ({
      code: suggestion.code,
      description: suggestion.description,
      id: suggestion.id,
    }));
  }

  /**
   * Check whether a row is currently expanded in the BOM table.
   * @param rowId Row identifier.
   * @returns True when the row is expanded.
   */
  function isRowExpanded(rowId: string): boolean {
    return expandedRowIds.value.includes(rowId);
  }

  /**
   * Check whether a row is currently loading child BOM data.
   * @param rowId Row identifier.
   * @returns True when the row is loading children.
   */
  function isRowLoading(rowId: string): boolean {
    return loadingRowIds.value.includes(rowId);
  }

  /**
   * Expand or collapse a BOM row, lazily loading its children on first expand.
   * @param rowId Row identifier.
   */
  async function toggleRowExpansion(rowId: string): Promise<void> {
    const row = findBomRow(componentTree.value, rowId);
    if (row?.hasChildren !== true) {
      return;
    }

    if (isRowExpanded(rowId)) {
      expandedRowIds.value = expandedRowIds.value.filter(id => id !== rowId);
      return;
    }

    if (!row.isChildrenLoaded) {
      loadingRowIds.value = [...loadingRowIds.value, rowId];

      try {
        const children = await getBomChildren(row.materialDefinitionId, plant.value);
        const mappedChildren = children.map(child => mapBomRow(child, rowId, row.level + 1));

        componentTree.value = replaceBomRow(componentTree.value, rowId, currentRow => ({
          ...currentRow,
          children: mappedChildren,
          isChildrenLoaded: true,
        }));
      }
      finally {
        loadingRowIds.value = loadingRowIds.value.filter(id => id !== rowId);
      }
    }

    expandedRowIds.value = [...expandedRowIds.value, rowId];
  }

  /**
   * Load the BOM for the selected material.
   * @param materialCode Selected material code.
   * @param description Optional material description from search suggestions (unused, fetched from API).
   * @param materialDefinitionId Optional material definition ID from navigation state.
   */
  async function applySelectedMaterial(
    materialCode: string,
    description?: string | null,
    materialDefinitionId?: number,
  ): Promise<void> {
    selectedMaterialCode.value = materialCode;
    const normalizedDescription = typeof description === 'string'
      ? description.trim()
      : undefined;
    selectedMaterialDescription.value = normalizedDescription === undefined || normalizedDescription === ''
      ? undefined
      : normalizedDescription;
    componentTree.value = [];
    expandedRowIds.value = [];
    loadingRowIds.value = [];
    isLoadingBom.value = true;

    try {
      if (materialDefinitionId === undefined) {
        selectedMaterialDefinitionId.value = undefined;
        selectedBom.value = null;
        return;
      }

      selectedMaterialDefinitionId.value = materialDefinitionId;
      selectedBom.value = await getBomVisualization(materialDefinitionId, plant.value, {
        materialCode,
        materialDescription: selectedMaterialDescription.value,
      });
      componentTree.value = selectedBom.value?.components.map(component => mapBomRow(component)) ?? [];
      selectedMaterialDescription.value
        = selectedMaterialDescription.value
          ?? selectedBom.value?.header.materialDescription
          ?? undefined;
    }
    finally {
      isLoadingBom.value = false;
    }

    resetTablePage();
  }

  /**
   * Clear the selected material and loaded BOM state.
   */
  function clearSelection(): void {
    selectedMaterialCode.value = undefined;
    selectedMaterialDescription.value = undefined;
    selectedMaterialDefinitionId.value = undefined;
    selectedBom.value = null;
    suggestions.value = [];
    componentTree.value = [];
    expandedRowIds.value = [];
    loadingRowIds.value = [];
    resetTablePage();
  }

  /**
   * Clear loaded BOM data while preserving the current search term behavior in the view.
   */
  function clearBom(): void {
    selectedMaterialCode.value = undefined;
    selectedMaterialDescription.value = undefined;
    selectedMaterialDefinitionId.value = undefined;
    selectedBom.value = null;
    componentTree.value = [];
    expandedRowIds.value = [];
    loadingRowIds.value = [];
    resetTablePage();
  }

  return {
    bomColumns,
    bomTablePagination,
    clearBom,
    clearSelection,
    componentRows,
    isLoadingBom,
    isLoadingSuggestions,
    applySelectedMaterial,
    loadSuggestions,
    isRowExpanded,
    isRowLoading,
    parentComponentCount,
    parentComponentRows,
    plant,
    selectedBom,
    selectedMaterialCode,
    selectedMaterialDescription,
    selectedMaterialDefinitionId,
    selectedMaterialLabel,
    setPlant,
    suggestions,
    toggleRowExpansion,
  };
});

