    axiosLib.delete(url, config),
};

let propertyDataTypeOptionsCache: Array<PropertyDataTypeOptionDto> | null = null;
let propertyDataTypeOptionsPromise: Promise<Array<PropertyDataTypeOptionDto>> | null = null;

type MaterialDefinitionResponse
  = MaterialDefinitionApi
    | WrappedApiResponse<MaterialDefinitionApi>
    | undefined;

/**
 * Build authorization headers when token is available.
 * @returns Headers object with bearer token, or empty object.
 */
function authHeaders(): Record<string, string> {
  if (typeof token === 'string' && token.length > 0) {
    return { authorization: `Bearer ${token}` };
  }

  return {};
}

/**
 * @param payload any
 * @returns true if the payload is an object that conforms to the WrappedApiResponse structure, false otherwise
 */
function isWrappedApiResponse<T>(
  payload: WrappedApiResponse<T> | T | undefined,
): payload is WrappedApiResponse<T> {
  return (
    typeof payload === 'object'
    && payload !== null
    && 'success' in payload
    && typeof (payload as { success?: unknown }).success === 'boolean'
    && 'statusCode' in payload
  );
}

/**
 * @param payload WrappedApiResponse payload from the API
 * @param fallbackMessage Message to use when the payload does not contain any messages
 * @returns The message from the payload or the fallback message
 */
function resolveWrappedMessage<T>(
  payload: WrappedApiResponse<T>,
  fallbackMessage: string,
): string {
  return payload.messages?.find(message => message.trim() !== '') ?? fallbackMessage;
}

/**
 * @param payload API response payload that may be wrapped in the standard API response envelope
 * @param fallbackMessage Message to use for errors when the payload is wrapped but does not contain any messages
 * @returns Unwrapped data from the payload, or the original payload if it is not wrapped
 */
function unwrapApiPayload<T>(
  payload: WrappedApiResponse<T> | T | undefined,
  fallbackMessage: string,
): T | undefined {
  if (!isWrappedApiResponse(payload)) {
    return payload;
  }

  if (!payload.success && payload.statusCode !== 404) {
    throw new Error(resolveWrappedMessage(payload, fallbackMessage));
  }

  return payload.data ?? undefined;
}

/**
 * Check whether a property data type label/code represents a list.
 * @param dataType Property data type label or code.
 * @returns True when the normalized data type is list.
 */
function isListDataType(dataType: string): boolean {
  return dataType.toLowerCase().split(/[\s_-]/).join('') === 'list';
}

/**
 * Load property data type options from the API.
 * @returns Array of PropertyDataTypeOptionDto.
 */
async function loadPropertyDataTypeOptions(): Promise<Array<PropertyDataTypeOptionDto>> {
  if (propertyDataTypeOptionsCache !== null) {
    return propertyDataTypeOptionsCache;
  }

  if (propertyDataTypeOptionsPromise !== null) {
    return propertyDataTypeOptionsPromise;
  }

  propertyDataTypeOptionsPromise = (async () => {
    const response: AxiosResponse<
      Array<PropertyDataTypeApi>
      | ApiArrayEnvelope<PropertyDataTypeApi>
      | WrappedApiResponse<Array<PropertyDataTypeApi> | ApiArrayEnvelope<PropertyDataTypeApi>>
      | undefined
    > = await axios.get(
      `${baseUrl}/isa95-material-model/property-data-type`,
      {
        headers: {
          ...authHeaders(),
          accept: '*/*',
        },
      },
    );

    const payload = unwrapApiPayload(
      response.data,
      'Failed to load property data types',
    );

    const options = extractArrayData(payload).map(item => ({
      code: item.code,
      id: item.id,
      label: formatPropertyDataTypeLabel(item.code),
    }));

    propertyDataTypeOptionsCache = options;
    propertyDataTypeOptionsPromise = null;
    return options;
  })();

  return propertyDataTypeOptionsPromise;
}

/**
 * Get the data type code for a property data type ID.
 * This function caches the property data types for efficient lookup.
 * @param propertyDataTypeId Property data type ID to find.
 * @returns Data type code (e.g., "boolean", "string") or undefined.
 */
export async function getPropertyDataTypeCodeById(
  propertyDataTypeId?: number,
): Promise<string | undefined> {
  if (propertyDataTypeId === undefined || propertyDataTypeId === null) {
    return undefined;
  }

  const options = await loadPropertyDataTypeOptions();
  const option = getPropertyDataTypeOptionById(options, propertyDataTypeId);
  return option?.code;
}

/**
 * Fetch material definitions from master API.
 * @param plant Plant identifier.
 * @param search Material code search term.
 * @param page Page number (1-based).
 * @param limit Number of items per page.
 * @returns Material definition items and total count.
 */
async function fetchMaterialDefinitions(
  plant: number,
  search?: string,
  page = 1,
  limit = 100,
): Promise<FetchMaterialDefinitionsResult> {
  const normalizedSearch = typeof search === 'string' ? search.trim() : '';
  const parameters: Record<string, number | string> = {
    languageCode: resolveLanguageCode(),
    limit,
    page,
    plant,
  };

  if (normalizedSearch !== '') {
    parameters.code = normalizedSearch;
  }

  const response: AxiosResponse<
    MaterialDefinitionPaginatedApi
    | WrappedApiResponse<MaterialDefinitionPaginatedApi>
    | undefined
  > = await axios.get(
    `${baseUrl}${MATERIAL_DEFINITION_PATH}`,
    {
      headers: authHeaders(),
      params: parameters,
    },
  );

  const payload = unwrapApiPayload(
    response.data,
    'Failed to retrieve material definitions',
  );

  const items = payload?.items ?? [];
  const total = payload?.total ?? items.length;

  return { items, total };
}

/**
 * Fetch material definitions mapped to the material table rows.
 * @param plant Plant identifier.
 * @param search Search text from the material field.
 * @returns Material list filtered by backend using code criteria.
 */
export async function getMaterials(plant: number, search?: string): Promise<Array<MaterialRowDto>> {
  const { items } = await fetchMaterialDefinitions(plant, search);
  return items.map(item => mapMaterialDefinitionToRow(item));
}

/**
 * Fetch a single page of material definitions.
 * @param plant Plant identifier.
 * @param page Page number (1-based).
 * @param limit Number of rows per page.
 * @param search Optional material code filter.
 * @returns Rows for the requested page and the total record count.
 */
export async function getMaterialsPage(
  plant: number,
  page: number,
  limit: number,
  search?: string,
): Promise<PaginatedMaterialsResult> {
  const { items, total } = await fetchMaterialDefinitions(plant, search, page, limit);
  return {
    rows: items.map(item => mapMaterialDefinitionToRow(item)),
    total,
  };
}

/**
 * Fetch material suggestions for the search input.
 * @param plant Plant identifier.
 * @param search Search text.
 * @returns Material code suggestions.
 */
export async function getMaterialSuggestions(
  plant?: number,
  search?: string,
): Promise<Array<MaterialSuggestionDto>> {
  const normalizedSearch = typeof search === 'string' ? search.trim() : '';

  if (normalizedSearch.length < 3) {
    return [];
  }

  const response: AxiosResponse<
    Array<MaterialSuggestionApi>
    | ApiArrayEnvelope<MaterialSuggestionApi>
    | WrappedApiResponse<Array<MaterialSuggestionApi> | ApiArrayEnvelope<MaterialSuggestionApi>>
    | undefined
  > = await axios.get(
    `${baseUrl}${MATERIAL_DEFINITION_PATH}/suggestions`,
    {
      headers: authHeaders(),
      params: {
        languageCode: resolveLanguageCode(),
        ...(plant === undefined ? {} : { plant }),
        search: normalizedSearch,
      },
    },
  );

  const payload = unwrapApiPayload(
    response.data,
