/**
 * Fetch a material definition lookup by material code.
 * @param materialCode Material identifier used for BOM lookup.
 * @param plant Plant identifier.
 * @returns Material lookup payload with ID, code, and description.
 */
export async function getMaterialLookupByCode(
  materialCode: string,
  plant: number,
): Promise<MaterialLookupDto | null> {
  const normalizedMaterialCode = materialCode.trim().toLowerCase();
  const { items } = await fetchMaterialDefinitions(plant, materialCode);
  const exactMatch = items.find(
    item => item.code.trim().toLowerCase() === normalizedMaterialCode,
  );
  const material = exactMatch ?? items[0];

  if (material === undefined) {
    return null;
  }

  return {
    code: material.code,
    description: material.description ?? undefined,
    id: material.id,
  };
}

