/**
 * Fetch material class properties for the material editor.
 * Non-custom properties are returned too so the UI can display integrated data
 * in a read-only state.
 * @param materialClassId Material class identifier.
 * @param languageCode Language code for descriptions.
 * @returns Property definitions for the editor.
 */
export async function getMaterialClassPropertiesForEditor(
  materialClassId: number,
  languageCode = resolveLanguageCode(),
): Promise<Array<MaterialEditorPropertyDto>> {
  const response: AxiosResponse<
    MaterialClassPropertiesApi
    | WrappedApiResponse<MaterialClassPropertiesApi>
    | undefined
  > = await axios.get(
    `${baseUrl}/isa95-material-model/material-class/${materialClassId}/properties`,
    {
      headers: {
        ...authHeaders(),
        accept: '*/*',
      },
      params: {
        languageCode: resolveLanguageCode(languageCode),
      },
    },
  );

  const payload = unwrapApiPayload(
    response.data,
    `Failed to retrieve material class properties for class ${materialClassId}`,
  );

  // Load data type options to populate dataType field
  const dataTypeOptions = await loadPropertyDataTypeOptions();
  const dataTypeById = new Map(dataTypeOptions.map(option => [option.id, option.code]));

  return (payload?.properties ?? [])
    .map((property) => {
      const propertySemantics = mapMaterialClassPropertySemantics(property.propertySemanticsJson);
      const propertyDataTypeId = property.propertyDataTypeId;

      return {
        allowedValues: propertySemantics.allowedValues,
        cardinality: propertySemantics.cardinality ?? 'single',
        classPropertyType: propertySemantics.classPropertyType ?? 'InstanceType',
        code: property.code,
        dataType:
          propertyDataTypeId !== undefined && propertyDataTypeId !== null
            ? dataTypeById.get(propertyDataTypeId)
            : undefined,
        defaultValue: property.defaultValue ?? propertySemantics.defaultValue,
        description: property.description ?? property.code,
        id: property.id,
        isCustom: property.isCustom ?? false,
        maxLength: property.length ?? undefined,
        parentMaterialClassPropertyId: property.parentMaterialClassPropertyId ?? undefined,
        propertyDataTypeId,
      };
    });
}

/**
