 * This endpoint is optimized for the details dialog initial load so the UI can
 * avoid making one properties request per assigned class.
 * @param materialId Material definition identifier.
 * @param languageCode Language code for descriptions.
 * @returns Property definitions grouped by material class id.
 */
export async function getAssignedMaterialClassPropertiesForEditor(
  materialId: number,
  languageCode = resolveLanguageCode(),
): Promise<Record<number, Array<MaterialEditorPropertyDto>>> {
  const response: AxiosResponse<
    Array<AssignedMaterialClassPropertiesApi>
