    | undefined
  >
    = await axios.get(
      `${baseUrl}${MATERIAL_DEFINITION_PATH}/${materialId}/assigned-class-properties`,
      {
        headers: {
          ...authHeaders(),
          accept: '*/*',
        },
        params: {
          languageCode: resolveLanguageCode(languageCode),
        },
      },
    );

  const payload = unwrapApiPayload(
    response.data,
    `Failed to retrieve assigned class properties for material ${materialId}`,
  );

  const dataTypeOptions = await loadPropertyDataTypeOptions();
  const dataTypeById = new Map(dataTypeOptions.map(option => [option.id, option.code]));

  return Object.fromEntries(
    (payload ?? []).map((group) => {
      const properties = (group.properties ?? []).map((property) => {
        const propertySemantics = mapMaterialClassPropertySemantics(
          property.propertySemanticsJson,
