 * Assign selected material classes to a material definition.
 * @param materialId Material definition numeric identifier.
 * @param materialClassIds Selected material class identifiers.
 * @param properties properties to assign to the material definition, grouped by material class. Optional for the initial implementation, but can be used to optimize the number of API calls when assigning classes and setting property values at the same time.
 * @returns Updated material details after assignment.
 */
export async function assignMaterialClasses(
  materialId: number,
  materialClassIds: Array<number>,
  properties?: Array<MaterialDefinitionPropertyInputApi>,
): Promise<MaterialDetailsDto> {
  const payload: AssignMaterialClassesPayload = {
    materialClassIds,
    properties,
  };

  const response: AxiosResponse<MaterialDefinitionResponse> = await axios.post(
    `${baseUrl}${MATERIAL_DEFINITION_PATH}/${materialId}/material-classes`,
    payload,
    {
      headers: {
        ...authHeaders(),
      },
    },
  );

  const responseData = unwrapApiPayload(
    response.data,
    `Failed to assign material classes for material ${materialId}`,
  );

  if (responseData !== undefined) {
    return mapMaterialDefinitionToDetails(responseData);
  }

  const fallbackResponse: AxiosResponse<MaterialDefinitionResponse> = await axios.get(
    `${baseUrl}${MATERIAL_DEFINITION_PATH}/${materialId}`,
    {
      headers: authHeaders(),
    },
  );

  const fallbackData = unwrapApiPayload(
    fallbackResponse.data,
    `Failed to load material definition ${materialId} after update`,
  );

  if (fallbackData === undefined) {
    throw new Error(`Material definition ${materialId} could not be loaded after update.`);
  }

  return mapMaterialDefinitionToDetails(fallbackData);
}

