import { isAxiosError } from 'axios';
import { getActiveLanguageCode } from '../../../../localization/i18n.ts';
import type {
  MaterialClassAssignmentDto,
  MaterialClassPropertyRowDto,
  MaterialDetailsDto,
  MaterialPropertyGroupDto,
  MaterialRowDto,
  PhysicalPropertyEntryDto,
  RelatedMaterialFieldDto,
  RelatedMaterialRowDto,
} from '../../materialDto/update-material.dto.ts';
import type {
  ApiArrayEnvelope,
  ApiErrorPayload,
  MaterialClassPropertyApi,
  MaterialClassPropertySemanticsApi,
  MaterialClassPropertySemanticsDto,
