  MaterialDefinitionApi,
  MaterialDefinitionPropertyApi,
  PropertyDataTypeOptionDto,
  RelatedMaterialApi,
} from '../interfaces/api.interface.ts';

/**
 * @param value Unknown value to test.
 * @returns True when the value is a non-empty string.
 */
function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim() !== '';
}

/**
 * @param value Unknown value to test.
 * @returns True when the value is a non-null object record.
 */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

/**
 * @param value Serialized JSON string that may contain a message field.
 * @returns Extracted message when the JSON shape is recognized.
 */
function getMessageFromSerializedJson(value: string): string | null {
  try {
    const parsed = JSON.parse(value) as unknown;
    return isRecord(parsed) ? getMessageFromValue(parsed.message) : null;
  }
  catch {
    return null;
  }
}

/**
 * @param value Error message string, possibly serialized JSON.
 * @returns Readable message when the string is not empty.
 */
function getMessageFromString(value: string): string | null {
  if (!isNonEmptyString(value)) {
    return null;
  }

  return getMessageFromSerializedJson(value) ?? value;
}

/**
 * @param value API payload message value.
 * @returns First readable message from a string or string array.
 */
function getMessageFromValue(value: unknown): string | null {
  if (typeof value === 'string') {
    return getMessageFromString(value);
  }

  if (Array.isArray(value)) {
    const messages: Array<unknown> = value;
    return messages.find((item): item is string => isNonEmptyString(item)) ?? null;
  }

  return null;
}

/**
 * @param payload Error payload from backend.
 * @returns Best effort message from wrapped or legacy payloads.
 */
function getMessageFromPayload(payload: ApiErrorPayload | string | undefined): string | null {
  if (typeof payload === 'string') {
    return getMessageFromString(payload);
  }

  const wrappedMessage = getMessageFromValue(payload?.messages);
  if (wrappedMessage !== null) {
    return wrappedMessage;
  }

  return getMessageFromValue(payload?.message);
}

/**
 * Extract a readable error message from backend/API failures.
 * Handles stringified JSON messages from the backend.
 * @param error Unknown error thrown by Axios or local code.
 * @returns Human-readable message when available.
 */
export function getApiErrorMessage(error: unknown): string | null {
  if (isAxiosError(error)) {
    const payload = error.response?.data as ApiErrorPayload | string | undefined;

    return getMessageFromPayload(payload);
  }

  if (error instanceof Error && isNonEmptyString(error.message)) {
    return error.message;
  }

  return null;
}

/**
 * Normalize a language code for backend requests, falling back to the active UI language.
 * @param languageCode Optional language code override.
 * @returns Two-letter uppercase language code.
 */
export function resolveLanguageCode(languageCode?: string): string {
  const normalizedLanguageCode = languageCode
    ?.trim()
    .split(/[-_]/)[0]
    ?.slice(0, 2)
    .toUpperCase();

  if ((normalizedLanguageCode != null) && normalizedLanguageCode.length > 0) {
    return normalizedLanguageCode;
  }

  return getActiveLanguageCode();
}

/**
 * Normalize list payloads that may come as raw arrays or paginated envelopes.
 * @param payload Raw payload from backend.
 * @returns Normalized array.
 */
export function extractArrayData<T>(
  payload: Array<T> | ApiArrayEnvelope<T> | undefined,
): Array<T> {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (payload !== undefined && Array.isArray(payload.items)) {
    return payload.items;
  }

  if (payload !== undefined && Array.isArray(payload.data)) {
    return payload.data;
  }

  return [];
}

/**
 * @returns A human-readable label for a property data type code.
 * @param code Property data type code.
 */
export function formatPropertyDataTypeLabel(code: string): string {
  return code
    .toLowerCase()
    .split('_')
    .filter(Boolean)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

/**
 * @param options PropertyDataTypeOptionDto array to search within.
 * @param propertyDataTypeId Property data type ID to find.
 * @returns Matching PropertyDataTypeOptionDto or undefined.
 */
export function getPropertyDataTypeOptionById(
  options: Array<PropertyDataTypeOptionDto>,
  propertyDataTypeId?: number,
): PropertyDataTypeOptionDto | undefined {
  return options.find(option => option.id === propertyDataTypeId);
}

/**
 * @param length length value from the form, expected to be a non-negative integer or empty.
 * @returns Parsed length as number or null.
 */
export function parsePropertyLength(length: string): number | null {
  const normalizedLength = length.trim();

  if (normalizedLength === '' || normalizedLength === '-') {
    return null;
  }

  const parsedLength = Number(normalizedLength);
  if (!Number.isInteger(parsedLength) || parsedLength < 0) {
    throw new Error('Length must be a non-negative integer.');
  }

  return parsedLength;
}

/**
 * Parse a property default value from the form.
 * @param defaultValue Default value from the form, expected to be a string or empty.
 * @returns Parsed default value as string or null.
 */
export function parsePropertyDefaultValue(defaultValue: string): string | null {
  const normalizedDefaultValue = defaultValue.trim();

  if (normalizedDefaultValue === '' || normalizedDefaultValue === '-') {
    return null;
  }

  return normalizedDefaultValue;
}

/**
 * Parse semicolon-separated allowed values from the property form.
 * @param value Raw values entered as "A; B; C".
 * @returns Normalized allowed values or null when empty.
 */
export function parsePropertyAllowedValues(value: string): Array<string> | null {
  const allowedValues = value
    .split(';')
    .map(item => item.trim())
    .filter(item => item.length > 0);

  return allowedValues.length > 0 ? allowedValues : null;
}

/**
 * Normalize raw allowed values from semantic JSON.
 * @param value Raw allowed values from camelCase, snake_case, or string format.
 * @returns String array when values are present.
 */
function normalizeAllowedValues(value: unknown): Array<string> | undefined {
  if (Array.isArray(value)) {
    const allowedValues = value
      .map(item => typeof item === 'string' ? item.trim() : String(item).trim())
      .filter(item => item.length > 0);

    return allowedValues.length > 0 ? allowedValues : undefined;
  }

  if (typeof value === 'string') {
    return parsePropertyAllowedValues(value) ?? undefined;
  }

  return undefined;
}

/**
 * Check whether a raw API value is a supported class property type.
 * @param value Raw API value.
 * @returns True when the value is a valid class property type.
 */
function isMaterialClassPropertyType(value: unknown): value is MaterialClassPropertyType {
  return value === 'ClassType' || value === 'InstanceType' || value === 'DefaultType';
}

/**
 * Normalize raw property semantics from the backend into UI-friendly camelCase keys.
 * @param propertySemanticsJson Raw property semantics JSON from the API.
 * @returns Normalized semantics DTO.
 */
export function mapMaterialClassPropertySemantics(
  propertySemanticsJson?: MaterialClassPropertySemanticsApi,
): MaterialClassPropertySemanticsDto {
  const classPropertyType = propertySemanticsJson?.classPropertyType;
  const rawClassPropertyType = typeof classPropertyType === 'string'
    ? classPropertyType
    : propertySemanticsJson?.class_property_type;
  const defaultValue = propertySemanticsJson?.defaultValue;
  const rawDefaultValue = typeof defaultValue === 'string'
    ? defaultValue
    : propertySemanticsJson?.default_value;
  const allowedValues = normalizeAllowedValues(
    propertySemanticsJson?.allowedValues ?? propertySemanticsJson?.allowed_values,
  );

  return {
    allowedValues,
    cardinality: propertySemanticsJson?.cardinality === 'array' ? 'array' : 'single',
    classPropertyType: isMaterialClassPropertyType(rawClassPropertyType)
      ? rawClassPropertyType
      : undefined,
    defaultValue: typeof rawDefaultValue === 'string' ? rawDefaultValue : undefined,
  };
}

/**
 * Map API material class property to table row DTO.
 * @param property API material class property.
 * @param materialClassId Material class ID.
 * @param propertyDataTypeOptions Array of PropertyDataTypeOptionDto to resolve data type labels.
 * @returns MaterialClassPropertyRowDto.
 */
export function mapMaterialClassPropertyToRow(
  property: MaterialClassPropertyApi,
  materialClassId: number,
  propertyDataTypeOptions: Array<PropertyDataTypeOptionDto>,
): MaterialClassPropertyRowDto {
  const propertySemantics = mapMaterialClassPropertySemantics(property.propertySemanticsJson);

  return {
    allowedValues: propertySemantics.allowedValues,
    cardinality: propertySemantics.cardinality ?? 'single',
    classId: materialClassId,
    classPropertyType: propertySemantics.classPropertyType ?? 'InstanceType',
    code: property.code,
    dataType:
      getPropertyDataTypeOptionById(
        propertyDataTypeOptions,
        property.propertyDataTypeId,
      )?.label ?? '-',
    defaultValue: property.defaultValue
      ?? propertySemantics.defaultValue
      ?? '',
    description: property.description ?? property.code,
    id: property.id,
    isCustom: property.isCustom,
    isUsedByMaterials: property.isUsedByMaterials,
    length: property.length === null || property.length === undefined
      ? '-'
      : String(property.length),
    propertyDataTypeId: property.propertyDataTypeId ?? 0,
  };
}

/**
 * Convert scalar values to displayable string.
 * @param value Input value.
 * @returns String representation or '-'.
 */
function scalarToString(value: unknown): string {
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    return value.map(item => scalarToString(item)).join(', ');
  }

  if (value !== null && typeof value === 'object') {
    return JSON.stringify(value);
  }

  return '-';
}

/**
 * Format code-like values for display.
 * Removes the CUST_ prefix, inserts spaces for camel/snake/kebab case,
 * and uppercases the first visible letter.
 * @param value Raw label value.
 * @returns Human-readable label or '-' when empty.
 */
export function formatDisplayValue(
  value: string | number | boolean | undefined | null,
): string {
  if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean') {
    return '-';
  }

  const trimmedValue = String(value).trim();
  if (trimmedValue === '') {
    return '-';
  }

  const withoutPrefix = trimmedValue
    .replace(/^CUST_/i, '')
    .split(/[_-]+/)
    .join(' ');

  let spaced = '';

  for (let index = 0; index < withoutPrefix.length; index += 1) {
    const current = withoutPrefix.charAt(index);
    const previous = withoutPrefix.charAt(index - 1);
    const next = withoutPrefix.charAt(index + 1);
    const isUpper = current >= 'A' && current <= 'Z';
    const previousIsLowerOrDigit = (previous >= 'a' && previous <= 'z')
      || (previous >= '0' && previous <= '9');
    const previousIsUpper = previous >= 'A' && previous <= 'Z';
    const nextIsLower = next >= 'a' && next <= 'z';

    if (index > 0 && isUpper && (previousIsLowerOrDigit || (previousIsUpper && nextIsLower))) {
      spaced += ' ';
    }

    spaced += current;
  }

  const normalizedValue = spaced
    .split(/\s+/)
    .filter(part => part.length > 0)
    .join(' ')
    .trim()
    .toLowerCase();

  if (normalizedValue.length === 0) {
    return '-';
  }

  return normalizedValue.charAt(0).toUpperCase() + normalizedValue.slice(1);
}

/**
 * Normalize a code-like string into a display label.
 * @param code Raw code string.
 * @returns Human-readable label with spaces.
 */
export function formatCodeAsLabel(code: string): string {
  return formatDisplayValue(code);
}

/**
 * Format an API property key for display in the related materials panel.
 * @param key Raw API key.
 * @returns Human-readable label.
 */
function formatRelatedMaterialFieldLabel(
  key: string,
): string {
  const normalizedKey = Array.from(key).reduce<string>((result, character, index) => {
    const isUppercase = character >= 'A' && character <= 'Z';

    if (index > 0 && isUppercase) {
      return `${result}_${character}`;
    }

    return `${result}${character}`;
  }, '');

  return normalizedKey
    .split('_')
    .filter((part): part is string => part.length > 0)
    .map((part: string) => {
      if (part.length <= 2) {
        return part.toUpperCase();
      }

      return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    })
    .join('_');
}

/**
 * Build the display field list for a related material card.
 * @param item Related material payload from the API.
 * @param propertyValues Matched class-specific properties.
 * @returns Ordered list of fields to render.
 */
function buildRelatedMaterialFields(
  item: RelatedMaterialApi,
  propertyValues: Record<string, unknown> | undefined,
): Array<RelatedMaterialFieldDto> {
  const fields: Array<RelatedMaterialFieldDto> = [];

  if (typeof item.description === 'string' && item.description.trim() !== '') {
    fields.push({
      key: 'materialDescription',
      label: 'Material_Description',
      value: item.description,
    });
  }

  for (const [key, rawValue] of Object.entries(propertyValues ?? {})) {
    if (rawValue === null || rawValue === undefined) {
      continue;
    }

    const value = scalarToString(rawValue);
    if (value === '-') {
      continue;
    }

    fields.push({
      key,
      label: formatRelatedMaterialFieldLabel(key),
      value,
    });
  }

  return fields;
}

/**
 * Map related materials API payload to the dialog row DTO.
 * @param item Related material payload from the API.
 * @param materialClassId Selected material class identifier.
 * @returns Related material row for the UI.
 */
export function mapRelatedMaterialToRow(
  item: RelatedMaterialApi,
  materialClassId: number,
): RelatedMaterialRowDto {
  const matchingProperty = item.properties?.find(
    property => property.materialClassId === materialClassId,
  );
  const propertyValues = matchingProperty?.propertiesJson;

  return {
    classId: matchingProperty?.materialClassId ?? materialClassId,
    description: item.description ?? undefined,
    fields: buildRelatedMaterialFields(item, propertyValues),
    id: item.id,
    materialCode: item.code,
  };
}

/**
 * Read a property value by key from ISA-95 material properties list.
 * @param properties Material properties array.
 * @param key Property key to resolve.
 * @returns Resolved value as string or '-'.
 */
function getPropertyValue(
  properties: Array<MaterialDefinitionPropertyApi> | undefined,
  key: string,
): string {
  if (properties === undefined) {
    return '-';
  }

  for (const property of properties) {
    const values = property.values;
    if (values === undefined) {
      continue;
    }

    const matchedEntry = Object.entries(values).find(([propertyKey]) => propertyKey === key);
    if (matchedEntry === undefined) {
      continue;
    }

    const [, value] = matchedEntry;
    if (value === null || value === undefined) {
      continue;
    }

    return scalarToString(value);
  }

  return '-';
}

/**
 * Read a raw property value by any of the supported key spellings.
 * @param properties Material properties array.
 * @param keys Property keys to resolve.
 * @returns Raw property value when found.
 */
function getRawPropertyValue(
  properties: Array<MaterialDefinitionPropertyApi> | undefined,
  keys: Array<string>,
): unknown {
  if (properties === undefined) {
    return undefined;
  }

  const normalizedKeys = new Set(keys.map(key => key.toLowerCase()));

  for (const property of properties) {
    const values = property.values;
    if (values === undefined) {
      continue;
    }

    const matchedEntry = Object.entries(values).find(([propertyKey]) =>
      normalizedKeys.has(propertyKey.toLowerCase()),
    );
    if (matchedEntry !== undefined) {
      return matchedEntry[1];
    }
  }

  return undefined;
}

/**
 * Normalize list-like API values for display in chips/table cells.
 * @param value Raw API value.
 * @returns String list, including object.value entries.
 */
function normalizeDisplayList(value: unknown): Array<string> {
  if (Array.isArray(value)) {
    return value.flatMap(item => normalizeDisplayList(item));
  }

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const displayValue = String(value).trim();
    return displayValue === '' ? [] : [displayValue];
  }

  if (value !== null && typeof value === 'object' && 'value' in value) {
    return normalizeDisplayList((value as { value?: unknown }).value);
  }

  return [];
}

/**
 * Extract storage location codes from structured API values.
 * Handles both simple strings and complex objects with value, minimumStock, maximumStock.
 * @param value Raw API storage location value.
 * @returns Array of storage location codes.
 */
function extractStorageLocationCodes(value: unknown): Array<string> {
  if (Array.isArray(value)) {
    return value.flatMap(item => extractStorageLocationCodes(item));
  }

  if (typeof value === 'string' && value.trim() !== '') {
    return [value];
  }

  if (value !== null && typeof value === 'object' && 'value' in value) {
    const locationValue = (value as { value?: unknown }).value;
    if (typeof locationValue === 'string' && locationValue.trim() !== '') {
      return [locationValue];
    }
  }

  return [];
}

/**
 * Remove duplicate display values without changing their order.
 * @param values Display values.
 * @returns Unique display values.
 */
function uniqueDisplayValues(values: Array<string>): Array<string> {
  return Array.from(new Set(values));
}

/**
 * Resolve the material type displayed in the UI from materialType.
 * @param item API material definition.
 * @returns Display value for type column/field.
 */
function getMaterialType(item: MaterialDefinitionApi): string {
  const directMaterialType = item.materialType?.trim();
  if (typeof directMaterialType === 'string' && directMaterialType !== '') {
    return directMaterialType;
  }

  const propertyBasedMaterialType = normalizeDisplayList(
    getRawPropertyValue(item.properties, [
      'materialType',
      'MaterialType',
      'Material_Type',
    ]),
  ).join(', ');

  if (propertyBasedMaterialType !== '') {
    return propertyBasedMaterialType;
  }

  const directSpecialStockType = item.specialStockType?.trim();
  if (typeof directSpecialStockType === 'string' && directSpecialStockType !== '') {
    return directSpecialStockType;
  }

  const propertyBasedSpecialStockType = [
    getPropertyValue(item.properties, 'specialStockType'),
    getPropertyValue(item.properties, 'SpecialStockType'),
    getPropertyValue(item.properties, 'Special_Stock_Type'),
  ].find(value => value !== '-');

  if (typeof propertyBasedSpecialStockType === 'string' && propertyBasedSpecialStockType !== '') {
    return propertyBasedSpecialStockType;
  }

  return '-';
}

/**
 * Resolve storage locations from either the top-level field or nested inventory values.
 * @param item API material definition.
 * @returns Storage location codes for display.
 */
function getStorageLocations(item: MaterialDefinitionApi): Array<string> {
  const directStorageLocations = normalizeDisplayList(item.storageLocations);
  if (directStorageLocations.length > 0) {
    return uniqueDisplayValues(directStorageLocations);
  }

  const propertyStorageLocations = extractStorageLocationCodes(
    getRawPropertyValue(item.properties, [
      'storageLocations',
      'storageLocation',
      'StorageLocations',
      'StorageLocation',
    ]),
  );

  return uniqueDisplayValues(propertyStorageLocations);
}

/**
 * Map API material definition to table row DTO.
 * @param item API material definition.
 * @returns Material row DTO.
 */
export function mapMaterialDefinitionToRow(item: MaterialDefinitionApi): MaterialRowDto {
  return {
    description: item.description ?? '-',
    id: item.id,
    materialClasses: (item.materialClasses ?? []).map(materialClass => (
      materialClass.description ?? materialClass.code
    )),
    materialCode: item.code,
    storageLocations: getStorageLocations(item),
    type: getMaterialType(item),
  };
}

/**
 * Extract all key-value pairs from the physical property class.
 * @param properties Material properties array from the API.
 * @returns Ordered list of label/value entries.
 */
function extractPhysicalProperties(
  properties: Array<MaterialDefinitionPropertyApi> | undefined,
): Array<PhysicalPropertyEntryDto> {
  const physProperty = properties?.find(p => p.classCode === 'physicalProperty');

  if (physProperty?.valueDescriptions === undefined) {
    return [];
  }

  const valuesEntries = new Map(Object.entries(physProperty.values ?? {}));

  return Object.entries(physProperty.valueDescriptions).map(([key, label]) => {
    const raw: unknown = valuesEntries.get(key);
    let value: string;

    if (Array.isArray(raw)) {
      value = (raw as Array<unknown>).map(String).join(', ');
    }
    else if (raw === null || raw === undefined) {
      value = '-';
    }
    else if (typeof raw === 'object') {
      value = JSON.stringify(raw);
    }
    else {
      value = String(raw as string | number | boolean);
    }

    return { label, value };
  });
}

/**
 * Map class assignments from the API to the detail dialog model.
 * @param item API material definition.
 * @returns Class assignments for the editor.
 */
function extractMaterialClassAssignments(
  item: MaterialDefinitionApi,
): Array<MaterialClassAssignmentDto> {
  return (item.materialClasses ?? []).map(materialClass => ({
    code: materialClass.code,
    description: materialClass.description ?? materialClass.code,
    id: materialClass.id,
  }));
}

/**
 * Map property payloads from the API to class-based groups for the editor.
 * @param item API material definition.
 * @returns Property groups keyed by class.
 */
function extractMaterialPropertyGroups(
  item: MaterialDefinitionApi,
): Array<MaterialPropertyGroupDto> {
  return (item.properties ?? []).map(property => ({
    classCode: property.classCode ?? `Class ${property.materialClassId}`,
    classDescription:
      property.classDescription
      ?? property.classCode
      ?? `Class ${property.materialClassId}`,
    classId: property.materialClassId,
    values: { ...property.values },
  }));
}

/**
 * Map API material definition to detail dialog DTO.
 * @param item API material definition.
 * @returns Material details DTO.
 */
export function mapMaterialDefinitionToDetails(item: MaterialDefinitionApi): MaterialDetailsDto {
  const classAssignments = extractMaterialClassAssignments(item);

  return {
    classAssignments,
    classes: classAssignments.map(materialClass => materialClass.description),
    description: item.description ?? '-',
    id: item.id,
    materialCode: item.code,
    physicalProperties: extractPhysicalProperties(item.properties),
    propertyGroups: extractMaterialPropertyGroups(item),
    specialProcurement: getPropertyValue(item.properties, 'Special_Procurement'),
    storageLocations: getStorageLocations(item),
    type: getMaterialType(item),
  };
}

