export const SQL_IDENTIFIER_MAX_LENGTH = 128;

const SQL_IDENTIFIER_PATTERN = /^[A-Z_a-z]\w*$/;

/**
 * @param value  value to validate
 * @param label  label for the value
 * @returns validation message if invalid, empty string if valid
 */
export function getSqlIdentifierValidationMessage(
  value: string,
  label: string,
): string {
  const normalizedValue = value.trim();

  if (normalizedValue.length === 0) {
    return '';
  }

  if (normalizedValue.length > SQL_IDENTIFIER_MAX_LENGTH) {
    return `${label} must be ${SQL_IDENTIFIER_MAX_LENGTH} characters or fewer.`;
  }

  if (!SQL_IDENTIFIER_PATTERN.test(normalizedValue)) {
    return `${label} must start with a letter or underscore and use only letters, numbers, and underscores. Prefer camelCase, for example: myCode.`;
  }

  return '';
}

/**
 * @param value  value to validate
 * @returns true if value is a valid SQL identifier, false otherwise
 */
export function isValidSqlIdentifier(value: string): boolean {
  return (
    value.trim().length > 0
    && getSqlIdentifierValidationMessage(value, 'Value') === ''
  );
}

