  rows?: Array<OperationSegmentApi>
  total?: number
  limit?: number
  page?: number
}

/**
 * Check whether a payload item follows the grouped operation segment shape.
 * @param item Candidate payload entry.
 * @returns True when the item includes a rows array.
 */
function isOperationSegmentGroupApi(item: unknown): item is OperationSegmentGroupApi {
  return (
    typeof item === 'object'
    && item !== null
    && 'rows' in item
    && Array.isArray((item as { rows?: unknown }).rows)
  );
}

/**
 * Check whether all payload entries follow the grouped operation segment shape.
 * @param items Candidate payload entries.
 * @returns True when every entry includes a rows array.
 */
function isOperationSegmentGroupApiArray(
  items: Array<OperationSegmentApi | OperationSegmentGroupApi>,
): items is Array<OperationSegmentGroupApi> {
  return items.every(item => isOperationSegmentGroupApi(item));
}

interface WrappedApiResponse<T> {
  success: boolean
  statusCode: number
  messages?: Array<string>
  data?: T | null
}

interface FilterMaterialApi {
  code: string
}

interface FilterEquipmentApi {
  equipment: string
}

interface OperationSegmentDetailResult {
  operationId: string
  description?: string
  material?: string
  equipment?: string
  effectiveStartDate?: string
  effectiveEndDate?: string
  hmacDuration?: string
  hmodDuration?: string
  hlodDuration?: string
}

type NormalizedOperationStatus = 'active' | 'inactive';
type BackendOperationStatus = 'Active' | 'Inactive';

/**
 * Convert internal normalized status values to the backend enum format.
 * @param status Internal lowercase status.
 * @returns Backend status value expected by the API.
 */
function toBackendOperationStatus(status: NormalizedOperationStatus): BackendOperationStatus {
  return status === 'active' ? 'Active' : 'Inactive';
}

/**
 * Normalize various API status representations into UI status values.
 * @param statusValue Status value from API payload.
 * @param effectiveEndDate Effective end date for fallback derivation.
 * @returns Normalized operation status.
 */
function normalizeOperationStatus(
  statusValue: unknown,
  effectiveEndDate?: string,
): NormalizedOperationStatus {
  if (typeof statusValue === 'boolean') {
    return statusValue ? 'active' : 'inactive';
  }

  if (typeof statusValue === 'string') {
    const normalized = statusValue.trim().toLowerCase();
    if (['active', 'enabled', 'true', '1', 'current'].includes(normalized)) {
      return 'active';
    }
    if (['inactive', 'disabled', 'false', '0', 'expired'].includes(normalized)) {
      return 'inactive';
    }
  }

  if (typeof effectiveEndDate === 'string' && effectiveEndDate.trim().length > 0) {
    const endDate = new Date(effectiveEndDate);
    if (!Number.isNaN(endDate.getTime())) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      return endDate >= today ? 'active' : 'inactive';
    }
  }

  return 'inactive';
}

/**
 * Build authorization headers when a token is available.
 * @returns Headers object with bearer token, or an empty object.
 */
function authHeaders(): Record<string, string> {
  if (typeof token === 'string' && token.length > 0) {
    return { authorization: `Bearer ${token}` };
  }

  return {};
}

/**
 * Check whether a payload follows the common wrapped API response contract.
 * @param payload Response payload that may be wrapped or raw.
 * @returns True when payload is a wrapped API response.
 */
function isWrappedApiResponse<T>(
  payload: WrappedApiResponse<T> | T | undefined,
): payload is WrappedApiResponse<T> {
  return (
    typeof payload === 'object'
    && payload !== null
    && 'success' in payload
    && typeof (payload as { success?: unknown }).success === 'boolean'
    && 'statusCode' in payload
  );
}

/**
 * Resolve a readable message from wrapped payload metadata.
 * @param payload Wrapped API payload.
 * @param fallbackMessage Fallback message.
 * @returns First non-empty API message or fallback text.
 */
function resolveWrappedMessage<T>(
  payload: WrappedApiResponse<T>,
  fallbackMessage: string,
): string {
  return payload.messages?.find(message => message.trim() !== '') ?? fallbackMessage;
}

/**
 * Normalize wrapped and raw payloads into a plain data payload.
 * @param payload Raw or wrapped payload.
 * @param fallbackMessage Message used for thrown bad-request errors.
 * @returns Unwrapped payload data when available.
 */
function unwrapApiPayload<T>(
  payload: WrappedApiResponse<T> | T | undefined,
  fallbackMessage: string,
): T | undefined {
  if (!isWrappedApiResponse(payload)) {
    return payload;
  }

  if (!payload.success && payload.statusCode === 400) {
    throw new Error(resolveWrappedMessage(payload, fallbackMessage));
  }

  return payload.data ?? undefined;
}

/**
 * Map a raw operation definition API item to the frontend row DTO.
 * @param item Raw operation definition response item.
 * @returns Normalized operation definition row.
 */
function mapToOperationDefinitionRow(
  item: OperationDefinitionApi,
): OperationDefinitionRowDto {
  const rawStatus: unknown = item.status ?? item.state ?? item.isActive ?? item.active;

  return {
    operationId: String(item.operationId ?? ''),
    description: item.description ?? '',
    material: (item.material ?? '').trim(),
    equipment: (item.equipment ?? '').trim(),
    status: normalizeOperationStatus(rawStatus, item.effectiveEndDate),
    version: item.version ?? '',
    effectiveStartDate: item.effectiveStartDate ?? '',
    effectiveEndDate: item.effectiveEndDate ?? '',
    operationBillId: item.operationBillId ?? '',
    groupCounter: item.groupCounter ?? '',
    taskGroupId: item.taskGroupId ?? '',
  };
}

/**
 * Map a raw operation segment API item to the frontend detail DTO.
 * @param item Raw operation segment details response item.
 * @returns Normalized operation segment details.
 */
function mapToOperationSegmentDetails(
  item: OperationSegmentApi,
): OperationSegmentDetailResult {
  const hasHmacDuration = item.hmacDuration !== undefined && item.hmacDuration !== null;
  const hasHmodDuration = item.hmodDuration !== undefined && item.hmodDuration !== null;
  const hasHlogDuration = item.hlogDuration !== undefined && item.hlogDuration !== null;

  return {
    operationId: (item.erpIdentifier ?? '').trim(),
    description: item.description ?? '',
    material: (item.material ?? '').trim(),
    equipment: (item.equipment ?? '').trim(),
    effectiveStartDate: item.effectiveStartDate ?? '',
    effectiveEndDate: item.effectiveEndDate ?? '',
    hmacDuration: hasHmacDuration ? String(item.hmacDuration) : '',
    hmodDuration: hasHmodDuration ? String(item.hmodDuration) : '',
    hlodDuration: hasHlogDuration ? String(item.hlogDuration) : '',
  };
}

/**
 * Fetch a paginated list of operation definitions.
 * @param plant Plant context.
 * @param page 1-based page number.
 * @param limit Rows per page.
 * @param equipment Optional equipment filter.
 * @param material Optional material filter.
 * @param status Optional status filter.
 * @returns Paginated operation definition rows.
 */
export async function getOperationDefinitionsPage(
  plant: number,
  page: number,
  limit: number,
  equipment?: string,
  material?: string,
  status?: NormalizedOperationStatus,
): Promise<{ rows: Array<OperationDefinitionRowDto>, total: number }> {
  const parameters: {
    plant: number
    limit: number
    page: number
    equipment?: string
    material?: string
    status?: BackendOperationStatus
  } = {
    plant,
    limit,
    page,
  };

  if (equipment !== undefined && equipment !== '') {
    parameters.equipment = equipment;
  }
  if (material !== undefined && material !== '') {
    parameters.material = material;
  }
  if (status !== undefined) {
    parameters.status = toBackendOperationStatus(status);
  }

  interface PaginatedDefinitionsResponse {
    rows: Array<OperationDefinitionApi>
    total: number
    limit: number
    page: number
  }

  const response: AxiosResponse<
    | PaginatedDefinitionsResponse
    | Array<OperationDefinitionApi>
    | WrappedApiResponse<PaginatedDefinitionsResponse | Array<OperationDefinitionApi>>
    | undefined
  > = await axiosLib.get(
    `${baseUrl}${OPERATION_DEFINITIONS_PATH}`,
    { headers: authHeaders(), params: parameters },
  );

  const payload = unwrapApiPayload(
    response.data,
    'Failed to retrieve operation definitions',
  );
  const safePayload = payload ?? [];
  const definitionPayloadRows = !Array.isArray(safePayload) && Array.isArray(safePayload.rows) ? safePayload.rows : [];
  const items: Array<OperationDefinitionApi> = Array.isArray(safePayload) ? safePayload : definitionPayloadRows;
  const definitionPayloadTotal = !Array.isArray(safePayload) && typeof safePayload.total === 'number' ? safePayload.total : items.length;
  const total = Array.isArray(safePayload) ? items.length : definitionPayloadTotal;

  return {
    rows: items.map(item => mapToOperationDefinitionRow(item)),
    total,
  };
}

/**
 * Fetch equipment options for the definitions filter.
 * @param plant Plant context.
 * @param material Optional material filter.
 * @param signal Optional abort signal.
 * @returns Normalized equipment options.
 */
export async function fetchEquipmentOptions(
  plant: number,
  material?: string,
  signal?: AbortSignal,
): Promise<Array<EquipmentOptionDto>> {
  const parameters: Record<string, string | number> = { plant };
  if (material !== undefined && material !== '') {
    parameters.material = material;
  }

  const response: AxiosResponse<
    Array<FilterEquipmentApi>
    | WrappedApiResponse<Array<FilterEquipmentApi>>
    | undefined
  > = await axiosLib.get(
    `${baseUrl}${FILTER_EQUIPMENT_PATH}`,
    { headers: authHeaders(), params: parameters, signal },
  );

  const payload = unwrapApiPayload(
    response.data,
    'Failed to retrieve equipment options',
  );

  const items: Array<FilterEquipmentApi> = Array.isArray(payload)
    ? payload
    : [];

  return items.map((item) => {
    const code = item.equipment.trim();
    return { id: code, label: code };
  });
}

/**
 * Search material options for remote autocomplete.
