/**
 * Fetch full operation definition details.
 * @param operationId Operation definition identifier.
 * @returns Full operation definition details or null.
 */
export async function getOperationDefinitionDetails(
  operationId: number,
): Promise<OperationDefinitionRowDto | null> {
  const response: AxiosResponse<
    OperationDefinitionApi
    | null
    | WrappedApiResponse<OperationDefinitionApi>
    | undefined
  > = await axiosLib.get(
    `${baseUrl}${OPERATION_DEFINITIONS_PATH}/details/${operationId}`,
    { headers: authHeaders() },
  );

  const payload = unwrapApiPayload(
    response.data,
    `Failed to retrieve operation definition details for id ${operationId}`,
  );

  if (!payload) {
    return null;
  }

  return mapToOperationDefinitionRow(payload);
}

/**
 * Fetch operation segment rows for the segment tab.
 * @param options Segment query options.
 * @param options.plant Plant context.
 * @param options.material Optional material filter.
 * @param options.operationDefinitionId Optional operation definition filter.
 * @returns Operation segment rows and total count.
 */
export async function getOperationSegments(
  options: {
    plant: number
    material?: string
    operationDefinitionId?: number
  },
): Promise<{ rows: Array<OperationSegmentRowDto>, total: number }> {
  const {
    material,
    operationDefinitionId,
    plant,
  } = options;

  const path = material !== undefined && material !== ''
    ? `${baseUrl}${OPERATION_SEGMENTS_PATH}/by-material`
    : `${baseUrl}${OPERATION_SEGMENTS_PATH}`;
  const parameters: Record<string, string | number> = {
    plant,
  };

  if (material !== undefined && material !== '') {
    parameters.material = material;
  }
  else if (operationDefinitionId !== undefined) {
    parameters.operationDefinitionId = operationDefinitionId;
  }

  const response: AxiosResponse<
    | Array<OperationSegmentApi>
    | Array<OperationSegmentGroupApi>
    | PaginatedOperationSegmentsApi
    | WrappedApiResponse<
      Array<OperationSegmentApi>
      | Array<OperationSegmentGroupApi>
      | PaginatedOperationSegmentsApi
    >
    | undefined
  > = await axiosLib.get(
    path,
    { headers: authHeaders(), params: parameters },
  );

  const payload = unwrapApiPayload(
    response.data,
    'Failed to retrieve operation segments',
  );
  const safePayload = payload ?? [];

  const flattenGroupedSegments = (groups: Array<OperationSegmentGroupApi>): Array<OperationSegmentApi> =>
    groups.flatMap((group) => {
      const groupRows = Array.isArray(group.rows) ? group.rows : [];
      return groupRows.map(row => ({
        ...row,
        materialCode: row.materialCode ?? group.materialCode,
        groupCounter: row.groupCounter ?? group.groupCounter,
        taskGroupId: row.taskGroupId ?? group.taskGroupId,
        effectiveStartDate: row.effectiveStartDate ?? group.effectiveStartDate,
        effectiveEndDate: row.effectiveEndDate ?? group.effectiveEndDate,
      }));
    });

  let items: Array<OperationSegmentApi> = [];
  let total = 0;

  if (Array.isArray(safePayload)) {
    if (isOperationSegmentGroupApiArray(safePayload)) {
      items = flattenGroupedSegments(safePayload);
      total = items.length;
    }
    else {
      items = safePayload;
      total = items.length;
    }
  }
  else {
    const segmentPayloadRows = Array.isArray(safePayload.rows) ? safePayload.rows : [];
    items = segmentPayloadRows;
    total = typeof safePayload.total === 'number' ? safePayload.total : items.length;
  }

  const rows: Array<OperationSegmentRowDto> = items.map((item, index) => ({
    rowKey: ['seg', String(index)].join('-'),
    operationId: (item.operationNumber ?? item.erpIdentifier ?? '').trim(),
    material: (item.materialCode ?? item.material ?? '').trim(),
    equipment: (item.equipment ?? '').trim(),
    description: item.description ?? '',
    effectiveStartDate: item.effectiveStartDate ?? '',
    effectiveEndDate: item.effectiveEndDate ?? '',
    hmacDuration: item.hmacDuration !== undefined && item.hmacDuration !== null
      ? String(item.hmacDuration)
      : '',
    hmodDuration: item.hmodDuration !== undefined && item.hmodDuration !== null
      ? String(item.hmodDuration)
      : '',
    hlogDuration: item.hlogDuration !== undefined && item.hlogDuration !== null
      ? String(item.hlogDuration)
      : '',
    groupCounter: item.groupCounter ?? '',
    taskGroupId: item.taskGroupId ?? '',
    status: normalizeOperationStatus(
      item.status ?? item.state ?? item.isActive ?? item.active,
      item.effectiveEndDate,
    ),
  }));

  return {
    rows,
    total,
  };
}

/**
 * Fetch full operation segment details.
 * @param operationNumber Segment operation number.
 * @returns Full operation segment details or null.
 */
export async function getOperationSegmentDetails(
  operationNumber: string,
): Promise<OperationSegmentDetailResult | null> {
  const response: AxiosResponse<
    OperationSegmentApi
    | null
    | WrappedApiResponse<OperationSegmentApi>
    | undefined
  > = await axiosLib.get(
    `${baseUrl}${OPERATION_SEGMENTS_PATH}/${encodeURIComponent(operationNumber)}`,
    { headers: authHeaders() },
  );

  const payload = unwrapApiPayload(
    response.data,
    `Failed to retrieve operation segment details for ${operationNumber}`,
  );

  if (!payload) {
    return null;
  }

  return mapToOperationSegmentDetails(payload);
}

import {
  authorizeUser,
  AuthConfigService,
  ApiService,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
import { useRouter } from 'vue-router';
import { configuration } from '../../../Auth/configuration.ts';
import { useUserStore } from '../../../Auth/store/user-store.ts';
import { getUser, User } from '../../../Auth/user-service.ts';
import { AuthConfigDTO } from '../../../types/auth.config.dto.ts';
import { appLogger } from '../../../utils/logger/app-logger';

interface State {
  managedBy: string
  profile: string
  user: User | undefined
  userAttributes: Record<string, string>
}

const authconfig = new AuthConfigDTO(
  configuration.getAuthority(),
  configuration.getClientId(),
  configuration.getRedirectUri(),
  configuration.getResponseType(),
  configuration.getScopes(),
  new WebStorageStateStore({ store: globalThis.sessionStorage }),
  configuration.getAccessTokenExpiringNotificationTime(),
);

const umeBaseUrl = import.meta.env.UME_API_URL as string;
const OPERATION_APP_NAME = 'OPERATION-SCREEN';
const token = import.meta.env.TOKEN as string;

const redirectUri: string
  = (import.meta.env.APP_REDIRECT_URI as string | undefined) ?? '';
let appBasePath: string;
if (redirectUri !== '') {
  const parts: Array<string> = redirectUri.split('/');
  appBasePath = parts.pop() ?? '';
}

const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, token, OPERATION_APP_NAME);
const userAttributesManager = new UserAttributesManager(apiService);

export const useOperationProfileStore = defineStore('operation-user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      const { profile } = user;
      const fetchedUser = await apiService.getUserByEmail(profile.email);
      if (fetchedUser !== null && fetchedUser !== undefined) {
        localStorage.setItem('userId', fetchedUser.userId);
        await apiService.updateUserLastLoginByEmail(
          fetchedUser.email,
          new Date(),
        );
      }
      else {
        const userDetails = {
          firstName: profile.given_name,
          lastName: profile.family_name,
          email: profile.email,
          lastLogin: new Date(),
        };
        await apiService.saveUser(userDetails);
      }
      useUser.setProfile(`${profile.given_name} ${profile.family_name}`);
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes
          = userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes !== null && userAttributes !== undefined) {
          this.userAttributes = { ...userAttributes };
        }
        else {
          appLogger.warn('No user attributes found.');
        }
      }
      catch (error: unknown) {
        appLogger.error(
          `Error fetching user attributes: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    },
    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        await authService.logout();
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
      }
      catch {
        appLogger.error('Log out failed');
      }
    },
  },
  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    managedBy: '',
    profile: '',
    userAttributes: {} as Record<string, string>,
    user: undefined as User | undefined,
  }),
});

import { isCancel } from 'axios';
import { defineStore } from 'pinia';
import { ref } from 'vue';
import type {
  EquipmentOptionDto,
  MaterialOptionDto,
  OperationDefinitionRowDto,
  OperationStatus,
  OperationSegmentRowDto,
} from '../operationDto/operation.dto.ts';
import {
  fetchEquipmentOptions,
  getOperationDefinitionsPage,
  getOperationSegments,
  searchMaterialOptions,
} from '../service/api.ts';

const DEFAULT_ROWS_PER_PAGE = 5;
type OperationStatusFilter = OperationStatus | 'all';

let definitionMaterialSearchAbortController: AbortController | null = null;
let segmentMaterialSearchAbortController: AbortController | null = null;

export const useOperationStore = defineStore('operation', () => {
  const plant = ref(0);
  const rows = ref<Array<OperationDefinitionRowDto>>([]);
  const totalRows = ref(0);
  const currentPage = ref(1);
  const rowsPerPage = ref(DEFAULT_ROWS_PER_PAGE);

  const equipmentOptions = ref<Array<EquipmentOptionDto>>([]);
  const equipmentCacheKey = ref('');
  const isEquipmentLoading = ref(false);
  const selectedEquipment = ref<string | undefined>(undefined);
  const selectedStatus = ref<OperationStatusFilter>('all');

  const materialSearchResults = ref<Array<MaterialOptionDto>>([]);
  const isMaterialSearching = ref(false);
  const selectedMaterial = ref<string | undefined>(undefined);

  const segmentRows = ref<Array<OperationSegmentRowDto>>([]);
  const segmentTotalRows = ref(0);
  const isSegmentRowsLoading = ref(false);
  const segmentMaterialSearchResults = ref<Array<MaterialOptionDto>>([]);
  const isSegmentMaterialSearching = ref(false);

  /**
   * Store the plant context for all operation calls.
   * @param newPlant Plant identifier from the user profile.
   */
  function setPlant(newPlant: number): void {
    plant.value = newPlant;
  }

  /**
   * Load one page of operation definition rows.
   * @param page 1-based page number.
   * @param pageSize Optional rows per page (updates stored value).
   */
  async function loadRows(page = currentPage.value, pageSize?: number): Promise<void> {
    if (pageSize !== undefined) {
      rowsPerPage.value = pageSize;
    }
    try {
      const result = await getOperationDefinitionsPage(
        plant.value,
        page,
        rowsPerPage.value,
        selectedEquipment.value,
        selectedMaterial.value,
        selectedStatus.value === 'all' ? undefined : selectedStatus.value,
      );
      rows.value = result.rows;
      totalRows.value = result.total;
      currentPage.value = page;
    }
    catch (error) {
      console.error('Failed to load operation definitions:', error);
    }
  }

  /**
   * Lazily load equipment options and cache them by plant and material.
   * @param material Optional material filter for the equipment endpoint.
   */
  async function loadEquipmentOptions(material?: string): Promise<void> {
    const key = `${plant.value}:${material ?? ''}`;
    if (key === equipmentCacheKey.value) {
      return;
    }

    equipmentCacheKey.value = key;
    equipmentOptions.value = [];
    isEquipmentLoading.value = true;

    try {
      equipmentOptions.value = await fetchEquipmentOptions(plant.value, material);
    }
    catch {
      equipmentOptions.value = [];
    }
    finally {
      isEquipmentLoading.value = false;
    }
  }

  /**
   * Invalidate the cached equipment list.
   */
  function invalidateEquipmentCache(): void {
    equipmentCacheKey.value = '';
  }

  /**
   * Search material options for the definition tab autocomplete.
   * @param query Search term.
   * @param equipment Optional selected equipment filter.
   */
  async function searchMaterials(query: string, equipment?: string): Promise<void> {
    definitionMaterialSearchAbortController?.abort();
    definitionMaterialSearchAbortController = new AbortController();
    isMaterialSearching.value = true;

    try {
      materialSearchResults.value = await searchMaterialOptions(
        plant.value,
        query,
        equipment,
        definitionMaterialSearchAbortController.signal,
      );
    }
    catch (error) {
      if (isCancel(error)) {
        return;
      }
      materialSearchResults.value = [];
    }
    finally {
      isMaterialSearching.value = false;
    }
  }

  /**
   * Clear definition-tab material search state.
   */
  function clearMaterialSearch(): void {
    definitionMaterialSearchAbortController?.abort();
    definitionMaterialSearchAbortController = null;
    materialSearchResults.value = [];
    isMaterialSearching.value = false;
  }

  /**
   * Load operation segment rows for the segment tab.
   * @param operationDefinitionId Optional operation definition filter.
   * @param material Optional material filter.
   */
  async function loadSegmentRows(
    operationDefinitionId?: number,
    material?: string,
  ): Promise<void> {
    isSegmentRowsLoading.value = true;
    try {
      const result = await getOperationSegments({
        material,
        operationDefinitionId,
        plant: plant.value,
      });
      segmentRows.value = result.rows;
      segmentTotalRows.value = result.total;
    }
    catch (error) {
      console.error('Failed to load operation segments:', error);
      segmentRows.value = [];
      segmentTotalRows.value = 0;
    }
    finally {
      isSegmentRowsLoading.value = false;
    }
  }

  /**
   * Search material options for the segment tab autocomplete.
   * @param query Search term.
   * @param equipment Optional selected equipment filter.
   */
  async function searchSegmentMaterials(query: string, equipment?: string): Promise<void> {
    segmentMaterialSearchAbortController?.abort();
    segmentMaterialSearchAbortController = new AbortController();
    isSegmentMaterialSearching.value = true;

    try {
      segmentMaterialSearchResults.value = await searchMaterialOptions(
        plant.value,
        query,
        equipment,
        segmentMaterialSearchAbortController.signal,
      );
    }
    catch (error) {
      if (isCancel(error)) {
        return;
      }
      segmentMaterialSearchResults.value = [];
    }
    finally {
      isSegmentMaterialSearching.value = false;
    }
  }

  /**
   * Clear segment-tab material search state.
   */
  function clearSegmentMaterialSearch(): void {
    segmentMaterialSearchAbortController?.abort();
    segmentMaterialSearchAbortController = null;
    segmentMaterialSearchResults.value = [];
    isSegmentMaterialSearching.value = false;
  }

  /**
   * Clear the segment rows (used when entering the segment tab directly).
   */
  function clearSegmentRows(): void {
    segmentRows.value = [];
    segmentTotalRows.value = 0;
  }

  /**
   * Reset the definition-tab filters.
   */
  function resetFilters(): void {
    selectedEquipment.value = undefined;
    selectedMaterial.value = undefined;
    selectedStatus.value = 'all';
    currentPage.value = 1;
    clearMaterialSearch();
    invalidateEquipmentCache();
  }

  return {
    clearMaterialSearch,
    clearSegmentMaterialSearch,
    clearSegmentRows,
    currentPage,
    equipmentCacheKey,
    equipmentOptions,
    invalidateEquipmentCache,
    isEquipmentLoading,
    isMaterialSearching,
    isSegmentMaterialSearching,
    isSegmentRowsLoading,
    loadEquipmentOptions,
    loadRows,
    loadSegmentRows,
    materialSearchResults,
    plant,
    resetFilters,
    rows,
    searchMaterials,
    searchSegmentMaterials,
    segmentMaterialSearchResults,
    segmentRows,
    segmentTotalRows,
    selectedEquipment,
    selectedMaterial,
    selectedStatus,
    rowsPerPage,
    setPlant,
    totalRows,
  };
});

const DATE_PREFIX_PATTERN = /^(\d{4}-\d{2}-\d{2})/;

/**
 * Normalize API date strings for display in the same YYYY-MM-DD shape used by the database.
 * @param value Raw API date value that may be empty, null, or an ISO datetime string.
 * @returns A YYYY-MM-DD display value when a date prefix exists; otherwise the trimmed input or an empty string.
 */
export function formatOperationDate(value?: string | null): string {
  if (value === null || value === undefined) {
    return '';
  }

  const normalizedValue = value.trim();

  if (normalizedValue.length === 0) {
    return '';
  }

  const datePrefixMatch = DATE_PREFIX_PATTERN.exec(normalizedValue);

  if (datePrefixMatch) {
    return datePrefixMatch[1];
  }

  return normalizedValue;
}

import type { Router } from 'vue-router';

type SetupScreenTarget = 'equipment' | 'material';

interface SetupScreenConfig {
  path?: string
  routeName?: 'materials-filtered'
  tab: string
}

const materialSetupScreen: SetupScreenConfig = {
  routeName: 'materials-filtered',
  tab: 'materials',
};

const equipmentSetupScreen: SetupScreenConfig = {
  path: '/hry-set-ui/equipment',
  tab: 'equipment',
};

/**
 * Builds the query used to deep-link into a setup screen.
 * @param config Setup screen metadata for the target destination.
 * @param target Requested setup screen target.
 * @param code Material or equipment code to prefill.
 * @returns Query parameters for the destination screen.
 */
function buildQuery(
  config: SetupScreenConfig,
  target: SetupScreenTarget,
  code: string,
): Record<string, string> {
  if (target === 'material') {
    return {
      materialcode: code,
      tab: config.tab,
    };
  }

  return {
    equipmentcode: code,
    tab: config.tab,
  };
}

/**
 * Navigates to a setup screen with its filter state pre-applied.
 * @param router Vue Router instance for in-app material navigation.
 * @param target Requested setup screen target.
 * @param code Material or equipment code to prefill.
 */
export function navigateToSetupScreen(
  router: Router,
  target: SetupScreenTarget,
  code: string,
): void {
  const normalizedCode = code.trim();
  if (normalizedCode === '') {
    return;
  }

  if (target === 'material') {
    const query = buildQuery(materialSetupScreen, target, normalizedCode);
    router.push({
      name: materialSetupScreen.routeName,
      query,
    }).catch(() => {
      return;
    });
    return;
  }

  const query = buildQuery(equipmentSetupScreen, target, normalizedCode);
  const url = new URL(equipmentSetupScreen.path ?? '/', globalThis.location.origin);

  for (const [key, value] of Object.entries(query)) {
    url.searchParams.set(key, value);
  }

  globalThis.location.assign(url.toString());
}

