import { TableColumn } from '../types/table-column-type.ts';

/**
 * This function takes a table name and an array of table columns,
 * filters out the columns that are not visible, and returns a
 * semicolon-separated string of the hidden column names appended
 * with the table name.
 * @param tableName - The name of the table.
 * @param columns - An array of TableColumn objects.
 * @returns A semicolon-separated string of hidden column names prefixed with the table name.
 */
export function getHiddenColumnNames(
  tableName: string,
  columns: Array<TableColumn>,
): string {
  const hiddenColumns = columns.filter(column => column.visible === false);
  const hiddenColumnNames = hiddenColumns.map(
    column => `${column.name}_${tableName}`,
  );

  return hiddenColumnNames.join(';');
}

