import { getCurrentInstance, inject } from 'vue';

export interface AppNotificationAction {
  label: string
  handler?: () => void
}

export interface AppNotificationOptions {
  title?: string
  message?: string
  type?: 'info' | 'warning' | 'error' | 'success'
  timeout?: number
  actions?: Array<AppNotificationAction>
  position?: string
  onClose?: () => void
}

export interface AppNotify {
  show: (options: AppNotificationOptions) => unknown
  info: (options: AppNotificationOptions) => unknown
  warning: (options: AppNotificationOptions) => unknown
  error: (options: AppNotificationOptions) => unknown
  success: (options: AppNotificationOptions) => unknown
}

interface NotifyGlobalProperties {
  $notify?: AppNotify
}

const notifyInjectionKey = 'notify';

/**
 * @returns AppNotify instance from injection or global properties.
 */
export function useAppNotify(): AppNotify {
  const injectedNotify = inject<AppNotify | null>(notifyInjectionKey, null);
  if (injectedNotify !== null) {
    return injectedNotify;
  }

  const instance = getCurrentInstance();
  const globalNotify = (instance?.appContext.config.globalProperties as NotifyGlobalProperties | undefined)?.$notify;

  if (globalNotify !== undefined) {
    return globalNotify;
  }

  throw new Error('NotifyPlugin is not installed.');
}

